// Generator skema PostgreSQL dari database SQLite live (data/app.db).
// Jalankan:  node scripts/buat-skema-pg.mjs [SQLITE_FILE] [OUT_DIR]
// Keluaran:  pg-migrations/001_skema_pg.sql  (tabel + indeks, tanpa trigger)
// Trigger ditulis tangan di 002_pemicu_pg.sql (tidak bisa dikonversi mekanis).
//
// Aturan konversi (didokumentasikan di 001_skema_pg.sql):
//   INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
//   INTEGER lain                       -> BIGINT (agar cocok dengan PK untuk FK)
//   REAL                               -> NUMERIC(19,4)
//   INTEGER flag 0/1 (CHECK IN (0,1) atau nama aktif/pakai/bawaan/periode_aktif) -> BOOLEAN
//   TEXT DEFAULT strftime(datetime)    -> TIMESTAMPTZ DEFAULT now()
//   TEXT DEFAULT date()/strftime(date) -> DATE DEFAULT CURRENT_DATE
//   kolom JSON_TEKS                    -> JSONB
//   COLLATE NOCASE                     -> dibuang (pakai ILIKE / CITEXT di query)
import { DatabaseSync } from 'node:sqlite';
import fs from 'node:fs';
import path from 'node:path';

const SQLITE_FILE = process.argv[2] ?? 'data/app.db';
const OUT_DIR = process.argv[3] ?? 'pg-migrations';

// Kolom TEXT berisi JSON -> JSONB (hasil audit repo, Nov 2026)
const JSONB_COLS = new Set([
  'annual_processes.jumlah_hapus', 'annual_processes.pratinjau',
  'chat_match_logs.detail_json',
  'dashboard_layout.json', 'dashboard_layout_peran.json',
  'held_sales.data_json',
  'invoice_templates.blok', 'invoice_templates.teks',
  'invoices.data_json',
  'purchase_chat_logs.hasil_parse_json',
  'purchases.chat_rincian_json',
  'report_files.params_json', 'report_files.ringkas_json',
  'saved_reports.params_json', 'saved_reports.ringkas_json',
  'struk_profil.blok', 'struk_profil.teks',
]);

// Kolom tanggal TANPA default di SQLite -> DATE di PG (sisanya -> TIMESTAMPTZ)
const DATE_COLS = new Set([
  'annual_processes.sampai', 'annual_processes.periode_baru_dari',
  'payables.jatuh_tempo', 'receivables.jatuh_tempo',
  'report_files.periode_dari', 'report_files.periode_sampai',
]);

// Kolom TEXT yang BUKAN tanggal -> jangan disentuh (jam/hari sebagai string)
const TEXT_KECUALIKAN = new Set([
  'users.jam_dari', 'users.jam_sampai', 'users.hari_aktif',
]);

const BOOL_NAMA = new Set(['aktif', 'pakai', 'bawaan', 'periode_aktif',
  'direvisi', 'dibatalkan', 'dihitung_manual', 'diurungkan', 'diingat',
  'login_shift', 'perlu_ditinjau', 'tampil', 'wajib_ganti']);

// Tabel yang SELURUH kolom INTEGER DEFAULT 0/1-nya adalah flag -> BOOLEAN
// (counter seperti diskon_maks REAL tidak ikut karena tipenya bukan INTEGER)
const BOOL_TABEL = new Set(['role_hak_khusus']);

const db = new DatabaseSync(SQLITE_FILE, { readOnly: true });
const tabels = db
  .prepare("SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
  .all();

// Buang komentar baris `-- ...` dengan menghormati string literal '...'.
// WAJIB sebelum flatten: `.replace(/\s+/g,' ')` akan membuat `--` mengomentari
// sisa baris (kasus: CHECK alasan di sub_stock_docs).
function buangKomentar(sql) {
  let keluar = '';
  let kutip = false;
  for (let i = 0; i < sql.length; i++) {
    const ch = sql[i];
    if (kutip) {
      keluar += ch;
      if (ch === "'") {
        if (sql[i + 1] === "'") { keluar += sql[i + 1]; i++; }
        else kutip = false;
      }
      continue;
    }
    if (ch === "'") { kutip = true; keluar += ch; continue; }
    if (ch === '-' && sql[i + 1] === '-') {
      while (i < sql.length && sql[i] !== '\n') i++;
      continue;
    }
    keluar += ch;
  }
  return keluar;
}

// Pecah badan CREATE TABLE berdasarkan koma di kedalaman kurung 0.
function pecahBadan(badan) {
  const bagian = [];
  let dalam = 0, mulai = 0;
  for (let i = 0; i < badan.length; i++) {
    const ch = badan[i];
    if (ch === '(') dalam++;
    else if (ch === ')') dalam--;
    else if (ch === ',' && dalam === 0) { bagian.push(badan.slice(mulai, i)); mulai = i + 1; }
  }
  bagian.push(badan.slice(mulai));
  return bagian;
}

function konversiKolom(tabel, info, ekstra) {
  const { name, type, notnull, dflt_value: dflt, pk } = info;
  const kunci = `${tabel}.${name}`;
  const t = (type ?? 'TEXT').toUpperCase();
  const d = dflt ?? '';
  const ex = ekstra ?? {};
  // Klausa inline dari SQL asli yang wajib dipertahankan:
  // REFERENCES (FK) + CHECK non-boolean. UNIQUE inline ditangani sebagai UNIQUE(col).
  const ref = ex.references ? ` ${ex.references}` : '';
  const cek = ex.check ? ` ${ex.check}` : '';

  // 1. Primary key autoincrement (hanya bila SQL asli AUTOINCREMENT;
  //    mis. role_hak_khusus.role_id adalah PK manual -> BIGINT PRIMARY KEY biasa)
  if (pk === 1 && t === 'INTEGER' && (ekstra.pkCount ?? 1) === 1) {
    if (ekstra.autoInc) return `${name} BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY`;
    return `${name} BIGINT PRIMARY KEY${ref ? ` ${ref}` : ''}`.replace(/\s+/g, ' ').trim();
  }
  // 2. JSONB
  if (JSONB_COLS.has(kunci) && t === 'TEXT') {
    const dd = d === "'{}'" ? `DEFAULT '{}'::jsonb` : d ? `DEFAULT ${d}` : '';
    return `${name} JSONB ${notnull ? 'NOT NULL' : ''} ${dd}`.replace(/\s+/g, ' ').trim();
  }
  // 3. Default waktu SQLite -> now() / CURRENT_DATE (pasti kolom waktu)
  if (/strftime\('%Y-%m-%d %H:%M:%f', 'now'\)/.test(d)) {
    return `${name} TIMESTAMPTZ ${notnull ? 'NOT NULL' : ''} DEFAULT now()`.replace(/\s+/g, ' ').trim();
  }
  if (/date\('now'\)|strftime\('%Y-%m-%d', 'now'\)/.test(d)) {
    return `${name} DATE ${notnull ? 'NOT NULL' : ''} DEFAULT CURRENT_DATE`.replace(/\s+/g, ' ').trim();
  }
  // 4. Flag boolean INTEGER -> BOOLEAN (CHECK 0/1 bawaan dibuang, CHECK lain kept)
  const isBool = t === 'INTEGER' && (BOOL_NAMA.has(name) || BOOL_TABEL.has(tabel)
    || /CHECK\s*\(\s*\w+\s+IN\s*\(\s*0\s*,\s*1\s*\)/.test(d));
  if (isBool) {
    let dd = '';
    if (d === '1') dd = 'DEFAULT TRUE';
    else if (d === '0') dd = 'DEFAULT FALSE';
    return `${name} BOOLEAN ${notnull ? 'NOT NULL' : ''} ${dd}${ref}${cek}`.replace(/\s+/g, ' ').trim();
  }
  // 5. Numerik
  if (t === 'INTEGER') {
    let dd = '';
    if (d && !/^CHECK/i.test(String(d))) dd = `DEFAULT ${d}`;
    else if (/^CHECK/i.test(String(d))) dd = String(d);
    return `${name} BIGINT ${notnull ? 'NOT NULL' : ''} ${dd}${ref}${cek}`.replace(/\s+/g, ' ').trim();
  }
  if (t === 'REAL') {
    const dd = d ? `DEFAULT ${d}` : '';
    return `${name} NUMERIC(19,4) ${notnull ? 'NOT NULL' : ''} ${dd}${ref}${cek}`.replace(/\s+/g, ' ').trim();
  }
  // 5b. BLOB SQLite (impor_file_data) -> BYTEA
  if (t === 'BLOB') {
    const dd = d ? `DEFAULT ${d}` : '';
    return `${name} BYTEA ${notnull ? 'NOT NULL' : ''} ${dd}${ref}${cek}`.replace(/\s+/g, ' ').trim();
  }
  // 6. TEXT tanggal tanpa default
  if (t === 'TEXT' && !TEXT_KECUALIKAN.has(kunci)) {
    if (DATE_COLS.has(kunci)) {
      return `${name} DATE ${notnull ? 'NOT NULL' : ''}${ref}${cek}`.replace(/\s+/g, ' ').trim();
    }
    if (/tanggal|waktu|_pada$|_at$|sampai|periode_baru|dipulihkan|terakhir_|kunci_sampai/i.test(name)) {
      return `${name} TIMESTAMPTZ ${notnull ? 'NOT NULL' : ''}${ref}${cek}`.replace(/\s+/g, ' ').trim();
    }
  }
  // 7. Selain itu: pertahankan tipe + default asli
  const dd = d ? `DEFAULT ${d}` : '';
  return `${name} ${type} ${notnull ? 'NOT NULL' : ''} ${dd}${ref}${cek}`.replace(/\s+/g, ' ').trim();
}

let out = `-- ============================================================================
-- NusaSuite — Skema PostgreSQL (dihasilkan dari ${SQLITE_FILE})
-- Dibuat oleh: node scripts/buat-skema-pg.mjs  (boleh dijalankan ulang)
-- Jumlah tabel: ${tabels.length}
--
-- Konvensi konversi dari SQLite:
--   * INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT
--     AS IDENTITY PRIMARY KEY (BY DEFAULT agar import id lama tetap bisa)
--   * INTEGER lain -> BIGINT (wajib: tipe FK harus sama dengan PK yang diacu)
--   * REAL (harga/qty/total) -> NUMERIC(19,4) (uang presisi, tanpa float error)
--   * flag 0/1 (aktif/pakai/bawaan/periode_aktif + CHECK IN (0,1)) -> BOOLEAN
--   * TEXT DEFAULT strftime(datetime) -> TIMESTAMPTZ DEFAULT now()
--   * TEXT DEFAULT date()/strftime(date) -> DATE DEFAULT CURRENT_DATE
--   * kolom JSON teks (data_json, params_json, blok, teks struk, ...) -> JSONB
--   * settings.nilai SENGAJA tetap TEXT (campuran string biasa + array JSON)
--   * COLLATE NOCASE dibuang -> gunakan ILIKE / CITEXT di query (lihat db.pg.ts)
--   * Trigger ADA di 002_pemicu_pg.sql (ditulis tangan, bukan hasil generator)
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS citext;

`;

const fkAlter = [];
for (const t of tabels) {
  const infos = db.prepare(`PRAGMA table_info("${t.name.replace(/"/g, '""')}")`).all();
  const mSql = t.sql.match(/\(([\s\S]*)\)\s*;?\s*$/);
  const badan = mSql ? buangKomentar(mSql[1]) : '';
  const bagian = pecahBadan(badan);

  // Petakan klausa inline per kolom dari SQL asli: REFERENCES + CHECK.
  const ekstraKolom = {};
  for (const b of bagian) {
    const s = b.trim();
    if (/^(UNIQUE|CHECK|FOREIGN KEY|CONSTRAINT)\b/i.test(s)) continue;
    const m = s.match(/^"?(\w+)"?\s+\w+\s*(.*)$/is);
    if (!m) continue;
    const cn = m[1];
    let sisa = (m[2] ?? '').replace(/COLLATE\s+NOCASE/gi, '').trim();
    // Pisahkan REFERENCES ... (termasuk ON DELETE/UPDATE ...) dari sisanya.
    let references = '';
    const mr = sisa.match(/REFERENCES\s+"?\w+"?\s*\([^)]+\)(?:\s+ON\s+(?:DELETE|UPDATE)\s+(?:SET\s+NULL|SET\s+DEFAULT|CASCADE|RESTRICT|NO\s+ACTION|\w+))*/i);
    if (mr) { references = mr[0]; sisa = sisa.replace(mr[0], ' ').trim(); }
    // Ambil CHECK(...) inline (bisa lebih dari satu).
    const checks = [];
    const reCheck = /CHECK\s*\((?:[^()]|\([^()]*\))*\)/gi;
    let mc;
    while ((mc = reCheck.exec(sisa)) !== null) checks.push(mc[0]);
    // Buang CHECK boolean 0/1 (sudah terwakili BOOLEAN); pertahankan sisanya.
    const checksKeep = checks.filter((c) => !/IN\s*\(\s*0\s*,\s*1\s*\)/i.test(c));
    ekstraKolom[cn.toLowerCase()] = { references, check: checksKeep.join(' ') };
  }

  const unikLuar = [];
  const cekLuar = [];
  for (const b of bagian) {
    const s = b.trim();
    if (/^(UNIQUE|CHECK|FOREIGN KEY|CONSTRAINT)\b/i.test(s)) {
      let c = s.replace(/COLLATE\s+NOCASE/gi, '');
      c = c.replace(/\bINTEGER\b/gi, 'BIGINT').replace(/\bREAL\b/gi, 'NUMERIC(19,4)');
      if (/^UNIQUE/i.test(s)) unikLuar.push(c);
      else cekLuar.push(c);
    }
  }
  const pkCols = infos.filter((c) => c.pk > 0).sort((a, b) => a.pk - b.pk);
  const autoInc = /AUTOINCREMENT/i.test(t.sql);
  const kolomBaru = infos.map((c) => {
    const ex = { ...(ekstraKolom[c.name.toLowerCase()] ?? {}), pkCount: pkCols.length, autoInc };
    // SQLite mengizinkan REFERENCES ke tabel yang dibuat belakangan; PG tidak.
    // Maka FK dipindah ke ALTER TABLE di akhir file (lihat fkAlter).
    if (ex.references) {
      fkAlter.push(`ALTER TABLE ${t.name} ADD FOREIGN KEY (${c.name}) ${ex.references};`);
      ex.references = '';
    }
    let def = konversiKolom(t.name, c, ex);
    // PK teks/tunggal non-autoincrement (settings.kunci, ...) -> PRIMARY KEY inline
    if (c.pk === 1 && pkCols.length === 1 && c.type.toUpperCase() !== 'INTEGER') def += ' PRIMARY KEY';
    return '  ' + def;
  });
  const pkKomposit = pkCols.length > 1 ? [`  PRIMARY KEY (${pkCols.map((c) => c.name).join(', ')})`] : [];
  out += `CREATE TABLE ${t.name} (\n${kolomBaru.join(',\n')}`;
  const unikInline = [];
  for (const b of bagian) {
    const s = b.trim();
    if (/^(UNIQUE|CHECK|FOREIGN KEY|CONSTRAINT)\b/i.test(s)) continue;
    const m = s.match(/^"?(\w+)"?\s+\w+[^,]*\bUNIQUE\b/i);
    if (m && !/UNIQUE\s*\(/i.test(s)) unikInline.push(`  UNIQUE (${m[1]})`);
  }
  const tambahan = [...pkKomposit, ...unikInline, ...unikLuar.map((u) => '  ' + u), ...cekLuar.map((c) => '  ' + c)];
  if (tambahan.length) out += ',\n' + tambahan.join(',\n');
  out += `\n);\n\n`;
}

// Indeks asli SQLite (tanpa COLLATE NOCASE) — tetap dibuat di PG
const idx = db
  .prepare("SELECT sql FROM sqlite_master WHERE type='index' AND sql IS NOT NULL ORDER BY name")
  .all();
// Kolom boolean untuk penulisan ulang predikat indeks parsial (WHERE aktif = 1 -> TRUE)
const BOOL_SEMUA = [...BOOL_NAMA, 'lihat_hpp', 'ubah_harga_kasir', 'hapus_transaksi',
  'proses_tahunan', 'void_retur', 'buka_tutup_shift', 'lihat_laba', 'ubah_stok_manual',
  'sahkan_opname', 'hapus_massal', 'kelola_pengguna', 'ubah_pengaturan', 'akses_semua_toko'];
for (const r of idx) {
  let s = r.sql.replace(/COLLATE\s+NOCASE/gi, '');
  // Indeks parsial SQLite (WHERE bawaan = 1) tidak valid untuk BOOLEAN di PG.
  for (const b of BOOL_SEMUA) {
    s = s.replace(new RegExp(`\\b${b}\\s*=\\s*1\\b`, 'gi'), `${b} = TRUE`)
         .replace(new RegExp(`\\b${b}\\s*=\\s*0\\b`, 'gi'), `${b} = FALSE`);
  }
  out += s + ';\n';
}

// Kunci tamu TERPISAH di akhir agar urutan CREATE TABLE bebas
// (SQLite mengizinkan referensi maju, PostgreSQL tidak).
if (fkAlter.length) {
  out += '\n-- Kunci tamu (dipindah dari REFERENCES inline agar urutan tabel bebas)\n';
  for (const a of fkAlter) out += a + '\n';
}

fs.mkdirSync(OUT_DIR, { recursive: true });
const tujuan = path.join(OUT_DIR, '001_skema_pg.sql');
fs.writeFileSync(tujuan, out);
console.log(`OK: ${tabels.length} tabel + ${idx.length} indeks -> ${tujuan}`);
